begin;
select plan(15);
insert into auth.users (id,email) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a@example.test'),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','b@example.test');
insert into public.companies (id,name) values ('11111111-1111-4111-8111-111111111111','A'),('22222222-2222-4222-8222-222222222222','B');
insert into public.company_members(company_id,user_id,role) values ('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','admin'),('22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','admin');
set local role authenticated;
select set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);
select throws_ok($$select public.begin_verified_prospect_search('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','action-1','panaderias','Cordoba',5,'live')$$,'42501',null,'browser cannot start privileged provider request');
select throws_ok($$select public.finish_verified_prospect_search('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','action-1','panaderias','Cordoba',5,'live','[]')$$,'42501',null,'browser cannot forge provider results');
select throws_ok($$select public.save_prospect_search('11111111-1111-4111-8111-111111111111','forged','x','y','live','[]')$$,'42501',null,'browser cannot call legacy save');
select throws_ok($$select public.finish_prospect_search('11111111-1111-4111-8111-111111111111','action-1','panaderias','Cordoba',5,'live','[]')$$,'42501',null,'browser cannot call legacy finish');
select throws_ok($$select public.begin_prospect_search('11111111-1111-4111-8111-111111111111','action-1','panaderias','Cordoba',5,'live')$$,'42501',null,'browser cannot call legacy begin');
reset role;
set local role service_role;
select is(public.begin_verified_prospect_search('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','action-1','panaderias','Cordoba',5,'live')->>'state','started','first attempt starts');
select is(public.begin_verified_prospect_search('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','action-1','panaderias','Cordoba',5,'live')->>'state','pending','concurrent retry does not start provider again');
select lives_ok($$select public.finish_verified_prospect_search('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','action-1','panaderias','Cordoba',5,'live','[{"name":"Uno","phone":null,"website":"https://example.com","source_url":"https://example.com/"}]')$$,'server saves verified results');
select is(public.begin_verified_prospect_search('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','action-1','panaderias','Cordoba',5,'live')->>'state','completed','completed retry returns stored result');
select throws_ok($$select public.begin_verified_prospect_search('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','action-1','otro','Cordoba',5,'live')$$,'P0001',null,'reused action conflicts');
select throws_ok($$select public.begin_verified_prospect_search('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','action-1','panaderias','Cordoba',4,'live')$$,'P0001',null,'changed limit conflicts');
select throws_ok($$select public.begin_verified_prospect_search('22222222-2222-4222-8222-222222222222','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','action-2','panaderias','Cordoba',5,'live')$$,'42501',null,'cannot write another company');
reset role;
set local role authenticated;
select is((select count(*) from public.prospect_searches),1::bigint,'retry creates only one search');
select is((select count(*) from public.prospect_candidates),1::bigint,'retry creates only one candidate');
select set_config('request.jwt.claim.sub','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',true);
select is((select count(*) from public.prospect_candidates),0::bigint,'other company cannot read candidates');
reset role;
select * from finish();
rollback;
